use harness_tool_filesystem::{EditTool, ReadTool, SearchTool};
use harness_tool_shell::ExecTool;

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

struct BroadcastEventSink {
    tx: broadcast::Sender<AgentEventEnvelope>,
